# ---------------- Tac vu nen: xuat MP4, nghe video, dich bang Claude ----------------
DEFAULT_KEYS = []  # khong co mat khau co dinh trong code; neu khong dat gi se tu sinh mat khau ngau nhien moi lan chay
AUTO_KEY = False  # True khi mat khau la loai tu sinh
KEYS = []  # danh sach mat khau hop le (nhieu mat khau, dung mot trong cac mat khau la duoc)


def norm_key(x):
    return unicodedata.normalize("NFC", (x or "").strip())
KEY_FILE = os.path.join(os.path.expanduser("~"), ".vsmc_key")


def load_saved_keys():
    try:
        with open(KEY_FILE, encoding="utf-8") as f:
            return [norm_key(l) for l in f.read().splitlines() if norm_key(l)]
    except OSError:
        return []


def matkhau_cli(argv):
    """Dat / xoa / xem trang thai mat khau may chu (luu vao ~/.vsmc_key)."""
    import getpass
    ap = argparse.ArgumentParser(prog=os.path.basename(sys.argv[0]) + " matkhau")
    ap.add_argument("--xoa", action="store_true", help="xoa mat khau da luu")
    ap.add_argument("--xem", action="store_true", help="chi cho biet da dat mat khau chua")
    ap.add_argument("--dat", action="append", default=None, help="dat luon mat khau nay, dung nhieu lan de dat nhieu mat khau (khong hoi)")
    a = ap.parse_args(argv)
    if a.xem:
        n = len(load_saved_keys())
        print("Mat khau may chu: " + ("DA DAT %d mat khau (%s)" % (n, KEY_FILE) if n else "CHUA LUU (se tu sinh mat khau ngau nhien moi lan chay)"))
        return
    if a.xoa:
        try:
            os.remove(KEY_FILE)
            print("Da xoa mat khau may chu.")
        except OSError:
            print("Chua co mat khau de xoa.")
        return
    pws = [norm_key(x) for x in (a.dat or []) if norm_key(x)]
    if not pws:
        pw = getpass.getpass("Nhap mat khau may chu moi: ")
        if pw != getpass.getpass("Nhap lai de xac nhan: "):
            raise SystemExit("Hai lan nhap khong giong nhau. Chua luu.")
        pws = [norm_key(pw)]
    if any(len(x) < 8 for x in pws):
        raise SystemExit("Mat khau qua ngan (can it nhat 8 ky tu).")
    with open(KEY_FILE, "w", encoding="utf-8") as f:
        f.write("\n".join(pws) + "\n")
    try:
        os.chmod(KEY_FILE, 0o600)
    except OSError:
        pass
    print("Da luu mat khau may chu vao", KEY_FILE)
    print("Tu gio chay trang se tu dung mat khau nay. Nguoi dung tu xa nhap no vao o 'Mat khau may chu' tren trang.")
WORK = os.path.join(tempfile.gettempdir(), "vsmc")
os.makedirs(WORK, exist_ok=True)
JOBS, UP = {}, {}
def _env_mb(name, default_mb):
    try:
        return max(1, int(os.environ.get(name, default_mb))) * 1024 * 1024
    except ValueError:
        return default_mb * 1024 * 1024


MAX_UPLOAD = _env_mb("VSMC_MAX_UPLOAD_MB", 4096)  # toi da 4 GB moi file tai len (doi: bien VSMC_MAX_UPLOAD_MB)
DISK_RESERVE = 1024 ** 3  # luon chua lai it nhat 1 GB trong o dia sau khi nhan file
FILE_TTL = 3 * 3600  # file tam / tac vu cu hon 3 gio se bi xoa
MAX_JSON = 8 * 1024 * 1024  # toi da 8 MB cho moi yeu cau JSON
MAX_WORK = _env_mb("VSMC_MAX_WORK_MB", 12288)  # tong dung luong file tam toi da 12 GB (doi: bien VSMC_MAX_WORK_MB)
MAX_RUNNING = 2  # so tac vu nang (xuat MP4, nghe video, long tieng) chay cung luc
MAX_UPLOADING = 3  # so file duoc tai len cung luc
CONTACT = ""  # email lien he hien tren trang (--contact)
FORCE_HTTPS = False
LOOPBACK = ("127.0.0.1", "::1", "::ffff:127.0.0.1")
FAILS = {}  # ip -> (so lan sai, khoa den luc, moc dau)
FAIL_LOCK = threading.Lock()
DL_TOK = {}  # ma tai file dung 1 lan cho moi tac vu: token -> (job id, het han)
JOB_LOCK = threading.Lock()
UPLOAD_SEM = threading.BoundedSemaphore(MAX_UPLOADING)


class BusyError(Exception):
    pass


def _work_size():
    t = 0
    try:
        for n in os.listdir(WORK):
            try:
                t += os.path.getsize(os.path.join(WORK, n))
            except OSError:
                pass
    except OSError:
        pass
    return t


def cleanup_once():
    now = time.time()
    try:
        names = os.listdir(WORK)
    except OSError:
        return
    for n in names:
        fp = os.path.join(WORK, n)
        try:
            if now - os.path.getmtime(fp) > FILE_TTL:
                os.remove(fp)
        except OSError:
            pass
    for k, pth in list(UP.items()):
        if not os.path.exists(pth):
            UP.pop(k, None)
    for k, j in list(JOBS.items()):
        if j.get("status") != "running" and now - j.get("t", now) > FILE_TTL:
            JOBS.pop(k, None)
    for k, v in list(DL_TOK.items()):
        if v[1] < now:
            DL_TOK.pop(k, None)
    with FAIL_LOCK:
        for k, v in list(FAILS.items()):
            if v[1] < now and now - v[2] > 600:
                FAILS.pop(k, None)


def cleanup_loop():
    while True:
        time.sleep(600)
        cleanup_once()
FORBID = json.dumps({"error": "Chức năng này cần mật khẩu máy chủ. Hãy nhập đúng mật khẩu ở ô \"Mật khẩu máy chủ\"."},
                    ensure_ascii=False).encode("utf-8")


def run_job(fn, *a):
    jid = uuid.uuid4().hex[:12]
    with JOB_LOCK:
        if sum(1 for j in JOBS.values() if j.get("status") == "running") >= MAX_RUNNING:
            raise BusyError("Máy chủ đang bận xử lý các tác vụ khác. Vui lòng thử lại sau vài phút.")
        JOBS[jid] = {"status": "running", "progress": 0, "msg": "", "text": "", "file": None, "t": time.time()}

    def w():
        try:
            fn(JOBS[jid], *a)
            JOBS[jid]["status"] = "done"
        except RuntimeError as e:
            JOBS[jid].update(status="error", msg=str(e))
        except Exception:
            traceback.print_exc()
            JOBS[jid].update(status="error", msg="Lỗi xử lý, vui lòng thử lại.")
    threading.Thread(target=w, daemon=True).start()
    return jid


def _f(v, lo, hi, d=None):
    try:
        x = float(v)
    except Exception:
        x = lo if d is None else d
    return max(lo, min(hi, x))


def _dur(path):
    try:
        o = subprocess.run(["ffprobe", "-protocol_whitelist", "file", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", path],
                           capture_output=True, text=True, timeout=30).stdout.strip()
        return float(o)
    except Exception:
        return None


def build_filter(BL, voice, ov, av, vs, ass):
    f, last = [], "[0:v]"
    for i, r in enumerate((BL or [])[:20]):
        x, y = _f(r.get("x"), 0, 99), _f(r.get("y"), 0, 99)
        w = min(_f(r.get("w"), 1, 100), 100 - x) / 100
        h = min(_f(r.get("h"), 1, 100), 100 - y) / 100
        x, y = x / 100, y / 100
        s0, e0 = r.get("s"), r.get("e")
        en = ""
        if s0 not in ("", None) or e0 not in ("", None):
            en = ":enable='between(t,%.2f,%.2f)'" % (_f(s0 if s0 not in ("", None) else 0, 0, 1e9),
                                                    _f(e0 if e0 not in ("", None) else 1e9, 0, 1e9))
        f.append("%ssplit[m%d][c%d]" % (last, i, i))
        f.append("[c%d]crop=trunc(iw*%.4f):trunc(ih*%.4f):trunc(iw*%.4f):trunc(ih*%.4f),gblur=sigma=%.1f[b%d]"
                 % (i, w, h, x, y, _f(r.get("b"), 1, 60, 16) * 1.2, i))
        f.append("[m%d][b%d]overlay=trunc(W*%.4f):trunc(H*%.4f)%s[v%d]" % (i, i, x, y, en, i))
        last = "[v%d]" % i
    f.append(last + "ass=" + ass + "[vout]")
    if voice:
        t = _f(vs, 0.5, 2, 1)
        f.append("[0:a]volume=%.2f[a0];[1:a]%svolume=%.2f[a1];[a0][a1]amix=inputs=2:duration=first[aout]"
                 % (_f(ov, 0, 300, 25) / 100, ("atempo=%.2f," % t) if abs(t - 1) > 0.01 else "", _f(av, 0, 300, 100) / 100))
    return ";".join(f)


def render_job(job, p):
    if not shutil.which("ffmpeg"):
        raise RuntimeError("Máy chủ chưa cài ffmpeg (Termux: pkg install ffmpeg).")
    v = UP.get(p.get("video"))
    if not v:
        raise RuntimeError("Không tìm thấy video đã tải lên (file tạm tự xóa sau 3 giờ). Hãy tải lại.")
    a = UP.get(p.get("voice")) if p.get("voice") else None
    uid = uuid.uuid4().hex[:10]
    ass, out = uid + ".ass", uid + ".mp4"
    with open(os.path.join(WORK, ass), "w", encoding="utf-8") as fh:
        fh.write(p.get("ass") or "")
    cmd = ["ffmpeg", "-y", "-nostdin", "-progress", "pipe:1", "-nostats", "-protocol_whitelist", "file", "-i", v] + (["-protocol_whitelist", "file", "-i", a] if a else []) + [
        "-filter_complex", build_filter(p.get("BL"), bool(a), p.get("ov"), p.get("av"), p.get("vs"), ass),
        "-map", "[vout]"] + (["-map", "[aout]", "-c:a", "aac", "-b:a", "192k"] if a else ["-map", "0:a?", "-c:a", "copy"]) + [
        "-c:v", "libx264", "-preset", "veryfast", "-crf", "20", "-pix_fmt", "yuv420p", out]
    dur = _dur(v)
    logp = os.path.join(WORK, uid + ".log")
    with open(logp, "w") as log:
        pr = subprocess.Popen(cmd, cwd=WORK, stdout=subprocess.PIPE, stderr=log, text=True)
        for line in pr.stdout:
            if line.startswith("out_time_ms=") and dur:
                try:
                    job["progress"] = min(99, int(int(line.split("=")[1]) / 1e6 / dur * 100))
                except Exception:
                    pass
        rc = pr.wait()
    if rc != 0:
        print("FFmpeg loi:", open(logp, errors="ignore").read()[-600:], file=sys.stderr)
        raise RuntimeError("FFmpeg gặp lỗi khi xuất video. Chủ trang xem cửa sổ chạy máy chủ để biết chi tiết.")
    job.update(file=os.path.join(WORK, out), ctype="video/mp4", name="vietsub.mp4", progress=100)


def stt_job(job, p):
    path = UP.get(p.get("video"))
    if not path:
        raise RuntimeError("Không tìm thấy video đã tải lên (file tạm tự xóa sau 3 giờ). Hãy tải lại.")
    try:
        from faster_whisper import WhisperModel
    except ImportError:
        gk = os.environ.get("GROQ_API_KEY", "").strip()
        if not gk:
            raise RuntimeError("Máy chủ chưa cài faster-whisper và chưa đặt GROQ_API_KEY nên chưa nghe được video.")
        cues, lg = fast_stt(path, gk, p.get("lang") or "",
                            say=lambda d, n: job.update(progress=min(99, int(d * 100 / n))))
        job["lang"] = lg
        job["text"] = "".join("%d\n%s --> %s\n%s\n\n" % (i, srt_ts(a), srt_ts(b), t) for i, (a, b, t) in enumerate(cues, 1))
        job["progress"] = 100
        return
    m = WhisperModel(p.get("model") or "small", device="auto", compute_type="int8")
    segs, info = m.transcribe(path, language=p.get("lang") or None, vad_filter=True)
    job["lang"] = info.language

    def ts(t):
        return ("%02d:%02d:%06.3f" % (int(t // 3600), int(t % 3600 // 60), t % 60)).replace(".", ",")
    out = []
    for i, sg in enumerate(segs, 1):
        out.append("%d\n%s --> %s\n%s\n\n" % (i, ts(sg.start), ts(sg.end), sg.text.strip()))
        job["text"] = "".join(out)
        if info.duration:
            job["progress"] = min(99, int(sg.end / info.duration * 100))
    job["progress"] = 100


_TTS = {}


def clone_job(job, p):
    cues = [c for c in (p.get("cues") or []) if (c.get("text") or "").strip()]
    if not cues:
        raise RuntimeError("Không có phụ đề để đọc")
    ref = UP.get(p.get("ref"))
    if not ref:
        raise RuntimeError("Không tìm thấy file giọng mẫu đã tải lên")
    try:
        wav = ref_to_wav(ref, _f(p.get("start"), 0, 86400, 0))
    except SystemExit as e:
        raise RuntimeError(str(e))
    try:
        from mira.model import MiraTTS
        import soundfile as sf
    except ImportError:
        raise RuntimeError("Máy chủ chưa cài Vira-TTS hoặc soundfile nên chưa tạo được lồng tiếng.")
    if "m" not in _TTS:
        _TTS["m"] = MiraTTS("dolly-vn/Vira-TTS")
    tts = _TTS["m"]
    ctx = tts.encode_audio(wav)
    items = []
    for i, c in enumerate(cues, 1):
        audio = tts.generate(c["text"].strip(), ctx)
        items.append((_f(c.get("a"), 0, 1e7, 0), _f(c.get("b"), 0, 1e7, 0), audio.float().cpu().numpy().reshape(-1)))
        job["progress"] = min(99, int(i / len(cues) * 100))
    out = os.path.join(WORK, uuid.uuid4().hex[:10] + ".wav")
    sf.write(out, build_timeline(items), SR)
    job.update(file=out, ctype="audio/wav", name="long-tieng.wav", progress=100)


