GROQ_URL = "https://api.groq.com/openai/v1/audio/transcriptions"
UA = "vietsubminecratf/1.0"


def _http_json(req, tries=5, timeout=300):
    """Gui request; tu thu lai khi bi gioi han toc do (429) hoac may chu ban (5xx)."""
    for i in range(tries):
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return json.loads(r.read())
        except urllib.error.HTTPError as e:
            try:
                msg = e.read().decode("utf-8", "ignore")[:300]
            except Exception:
                msg = ""
            if e.code in (429, 500, 502, 503, 529) and i < tries - 1:
                try:
                    wait = float(e.headers.get("retry-after") or 0)
                except (ValueError, AttributeError):
                    wait = 0
                time.sleep(min(30, max(wait, 2 ** i)))
                continue
            raise RuntimeError("HTTP %s: %s" % (e.code, msg))
        except (urllib.error.URLError, socket.timeout, ConnectionError) as e:
            if i < tries - 1:
                time.sleep(2 ** i)
                continue
            raise RuntimeError("Loi mang: %s" % e)


def _multipart(fields, fname, fbytes, ctype):
    b = uuid.uuid4().hex
    parts = [('--%s\r\nContent-Disposition: form-data; name="%s"\r\n\r\n%s\r\n' % (b, k, v)).encode() for k, v in fields.items()]
    parts.append(('--%s\r\nContent-Disposition: form-data; name="file"; filename="%s"\r\nContent-Type: %s\r\n\r\n' % (b, fname, ctype)).encode())
    parts.append(fbytes)
    parts.append(("\r\n--%s--\r\n" % b).encode())
    return b"".join(parts), "multipart/form-data; boundary=" + b


def groq_transcribe(path, key, lang="", model="whisper-large-v3-turbo"):
    with open(path, "rb") as fh:
        data = fh.read()
    fields = {"model": model, "response_format": "verbose_json", "temperature": "0"}
    if lang:
        fields["language"] = lang
    body, ct = _multipart(fields, os.path.basename(path), data, "audio/mpeg")
    req = urllib.request.Request(GROQ_URL, data=body, method="POST",
                                 headers={"Authorization": "Bearer " + key, "Content-Type": ct, "User-Agent": UA})
    return _http_json(req)


def _extract_chunk(video, start, dur, out):
    r = subprocess.run(["ffmpeg", "-y", "-nostdin", "-v", "error", "-ss", "%.3f" % start, "-t", "%.3f" % dur, "-protocol_whitelist", "file", "-i", video,
                        "-vn", "-ac", "1", "-ar", "16000", "-c:a", "libmp3lame", "-b:a", "32k", out],
                       capture_output=True, text=True)
    if r.returncode != 0 or not os.path.exists(out):
        raise RuntimeError("FFmpeg loi khi tach am thanh: " + r.stderr[-200:])


def fast_stt(video, key, lang="", model="whisper-large-v3-turbo", seg=300, workers=6, say=None):
    """Cat am thanh thanh cac doan `seg` giay, tach + nghe song song. Tra ve (cues, ngon_ngu)."""
    if not shutil.which("ffmpeg"):
        raise RuntimeError("Máy chủ chưa cài ffmpeg (Termux: pkg install ffmpeg).")
    total = _dur(video)
    if not total:
        raise RuntimeError("Khong doc duoc do dai video (can ffprobe di kem ffmpeg)")
    n = max(1, int(-(-total // seg)))
    tmp = tempfile.mkdtemp(prefix="fast_", dir=WORK)
    results, langs = [None] * n, []

    def work(i):
        out = os.path.join(tmp, "c%03d.mp3" % i)
        _extract_chunk(video, i * seg, seg, out)
        j = groq_transcribe(out, key, lang, model)
        os.remove(out)
        segs = []
        for sg in j.get("segments") or []:
            t = (sg.get("text") or "").strip()
            if not t or (sg.get("no_speech_prob") or 0) > 0.8:
                continue
            segs.append((i * seg + float(sg["start"]), i * seg + float(sg["end"]), t))
        return i, segs, j.get("language")
    try:
        ex = concurrent.futures.ThreadPoolExecutor(max_workers=max(1, min(workers, n)))
        try:
            futs = [ex.submit(work, i) for i in range(n)]
            for d, f in enumerate(concurrent.futures.as_completed(futs), 1):
                i, segs, lg = f.result()
                results[i] = segs
                if lg:
                    langs.append(lg)
                if say:
                    say(d, n)
        except BaseException:
            ex.shutdown(wait=False, cancel_futures=True)
            raise
        else:
            ex.shutdown(wait=True)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    cues = sorted((c for r in results for c in r), key=lambda c: c[0])
    return cues, (langs[0] if langs else lang)


def _claude_lines(lines, key, model):
    prompt = _tr_prompt(lines)
    req = urllib.request.Request(
        "https://api.anthropic.com/v1/messages",
        data=json.dumps({"model": model, "max_tokens": 4096,
                         "messages": [{"role": "user", "content": prompt}]}).encode(),
        headers={"x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json", "User-Agent": UA},
        method="POST")
    j = _http_json(req, timeout=120)
    txt = "".join(c.get("text", "") for c in j.get("content", []) if c.get("type") == "text").strip()
    txt = re.sub(r"^```(?:json)?|```$", "", txt, flags=re.M).strip()
    arr = json.loads(txt)
    if not isinstance(arr, list) or len(arr) != len(lines):
        raise ValueError("Claude tra ve lech so dong")
    return [str(x) for x in arr]


def _claude_safe(lines, key, model):
    """Neu Claude tra ve lech so dong thi chia doi lo va dich lai; dong le van loi thi giu nguyen goc."""
    try:
        return _claude_lines(lines, key, model)
    except ValueError:
        if len(lines) <= 1:
            return list(lines)
        h = len(lines) // 2
        return _claude_safe(lines[:h], key, model) + _claude_safe(lines[h:], key, model)


def fast_translate(lines, key, model="claude-sonnet-5-5", batch=40, workers=8, say=None):
    chunks = [lines[i:i + batch] for i in range(0, len(lines), batch)]
    out = [None] * len(chunks)
    ex = concurrent.futures.ThreadPoolExecutor(max_workers=max(1, min(workers, len(chunks))))
    try:
        futs = {ex.submit(_claude_safe, c, key, model): k for k, c in enumerate(chunks)}
        for d, f in enumerate(concurrent.futures.as_completed(futs), 1):
            out[futs[f]] = f.result()
            if say:
                say(d, len(chunks))
    except BaseException:
        ex.shutdown(wait=False, cancel_futures=True)
        raise
    else:
        ex.shutdown(wait=True)
    flat = [t for c in out for t in c]
    return [t.strip() or o for t, o in zip(flat, lines)]


def nhanh_cli(argv):
    ap = argparse.ArgumentParser(prog=os.path.basename(sys.argv[0]) + " nhanh")
    ap.add_argument("--video", required=True, help="video hoac am thanh can nghe")
    ap.add_argument("--lang", default="", help="ma ngon ngu goc (en, zh, ja, ko...); bo trong = tu nhan")
    ap.add_argument("--out", default="goc.srt", help="phu de ngon ngu goc")
    ap.add_argument("--vi-out", default="phude_vi.srt", help="phu de tieng Viet")
    ap.add_argument("--no-dich", action="store_true", help="chi nghe, khong dich")
    ap.add_argument("--groq-key", default=os.environ.get("GROQ_API_KEY", ""), help="API key Groq (mien phi tai console.groq.com)")
    ap.add_argument("--key", default=os.environ.get("ANTHROPIC_API_KEY", ""), help="API key Anthropic")
    ap.add_argument("--model", default="claude-sonnet-5-5", help="model Claude de dich (sonnet chinh xac hon, haiku nhanh va re hon)")
    ap.add_argument("--stt-model", default="whisper-large-v3-turbo", help="whisper-large-v3-turbo (nhanh) hoac whisper-large-v3 (chinh xac hon)")
    ap.add_argument("--workers", type=int, default=6, help="so doan nghe song song")
    a = ap.parse_args(argv)
    if not a.groq_key:
        raise SystemExit("Thieu API key Groq: dat bien GROQ_API_KEY hoac dung --groq-key (lay mien phi o console.groq.com).")
    if not a.no_dich and not a.key:
        raise SystemExit("Thieu API key Anthropic: dat bien ANTHROPIC_API_KEY, dung --key, hoac them --no-dich de chi nghe.")
    t0 = time.time()
    cues, lg = fast_stt(a.video, a.groq_key.strip(), a.lang, a.stt_model, workers=a.workers,
                        say=lambda d, n: print("Da nghe %d/%d doan" % (d, n), flush=True))
    if not cues:
        raise SystemExit("Khong nghe duoc loi noi nao trong video.")
    write_srt(a.out, cues)
    print("Nghe xong %d cau (%s) sau %.0f giay -> %s" % (len(cues), lg or "?", time.time() - t0, a.out), flush=True)
    if a.no_dich:
        return
    vi = fast_translate([c[2] for c in cues], a.key.strip(), a.model,
                        say=lambda d, n: print("Da dich %d/%d lo" % (d, n), flush=True))
    write_srt(a.vi_out, [(c[0], c[1], t) for c, t in zip(cues, vi)])
    print("Xong phu de tieng Viet: %s (tong %.0f giay)" % (a.vi_out, time.time() - t0))


def main():
    if len(sys.argv) > 1 and sys.argv[1] == "nhanh":
        nhanh_cli(sys.argv[2:])
        return
    if len(sys.argv) > 1 and sys.argv[1] == "stt":
        stt_cli(sys.argv[2:])
        return
    if len(sys.argv) > 1 and sys.argv[1] == "matkhau":
        matkhau_cli(sys.argv[2:])
        return
    if len(sys.argv) > 1 and sys.argv[1] == "dich":
        dich_cli(sys.argv[2:])
        return
    if len(sys.argv) > 1 and sys.argv[1] == "tts":
        tts_cli(sys.argv[2:])
        return
    global KEYS, CONTACT, FORCE_HTTPS
    ap = argparse.ArgumentParser()
    ap.add_argument("--port", type=int, default=3000)
    ap.add_argument("--host", default="0.0.0.0", help="dia chi lang nghe; dung 127.0.0.1 khi chay sau proxy/tunnel HTTPS")
    ap.add_argument("--cert", default="", help="file chung chi HTTPS (fullchain.pem) de tu chay HTTPS")
    ap.add_argument("--cert-key", default="", help="file khoa rieng cua chung chi HTTPS (privkey.pem)")
    ap.add_argument("--force-https", action="store_true", help="chuyen HTTP sang HTTPS khi dung sau proxy co gui X-Forwarded-Proto")
    ap.add_argument("--contact", default=os.environ.get("VSMC_CONTACT", ""), help="email lien he hien tren trang")
    ap.add_argument("--key", action="append", default=None,
                    help="mat khau cho nguoi dung tu xa dung chuc nang may chu (xuat MP4, nghe video, AI); dung nhieu lan de dat nhieu mat khau")
    a = ap.parse_args()
    env = [x for x in re.split(r"[\n|]", os.environ.get("VSMC_KEY", "")) if x.strip()]
    global AUTO_KEY
    KEYS = [norm_key(x) for x in (a.key or env or load_saved_keys() or DEFAULT_KEYS) if norm_key(x)]
    if not KEYS:
        KEYS = [secrets.token_hex(10)]
        AUTO_KEY = True
    CONTACT = (a.contact or "").strip()
    FORCE_HTTPS = bool(a.force_https)
    if bool(a.cert) != bool(a.cert_key):
        raise SystemExit("Can dung dong thoi --cert va --cert-key.")
    serve(a.port, a.host, a.cert or None, a.cert_key or None)


if __name__ == "__main__":
    main()
